 const match = router([...itemRoutes, ...batchRoutes, ...orderRoutes, ...kitchenRoutes, ...planningRoutes, ...safetyRoutes]);

+function requestLanguage(headers) {
+  const header = Object.entries(headers).find(([name]) => name.toLowerCase() === "accept-language")?.[1];
+  if (typeof header !== "string") return config.defaultLanguage;
+  let best = 0;
+  let language = config.defaultLanguage;
+  for (const part of header.split(",")) {
+    const [tag, ...parameters] = part.trim().split(";");
+    if (!/^(en|ko)(?:-[a-z0-9]+)*$/i.test(tag)) continue;
+    const quality = parameters.length === 0 ? 1 :
+      parameters.length === 1 && /^\s*q\s*=\s*(?:0(?:\.\d{0,3})?|1(?:\.0{0,3})?)\s*$/i.test(parameters[0]) ?
+        Number(parameters[0].split("=")[1]) : 0;
+    if (quality > best) {
+      best = quality;
+      language = tag.slice(0, 2).toLowerCase();
+    }
+  }
+  return language;
+}
+
 /** Builds the request handler over a store. `clock` returns now (ms). */
 export function createApp(store, { clock = () => Date.now() } = {}) {
   return async function handle({ method = "GET", path, headers = {}, body = null }) {
     const url = new URL(path, "http://larder");
-    const lang = config.defaultLanguage;
+    const lang = requestLanguage(headers);
     try {
       const found = match(method, url.pathname);
       if (!found) throw new AppError("not_found");
@@ -36,7 +55,7 @@ export function createApp(store, { clock = () => Date.now() } = {}) {
